def _transcribe_audio(self, audio_path: Path) -> Optional[str]:
    self._log(f"Sending audio {audio_path.name} to OpenAI for transcription")
    try:
        with audio_path.open("rb") as audio_file:
            response = self.client.audio.transcriptions.create(
                model=config.API_SETTINGS["model"],
                file=audio_file,
                response_format=config.API_SETTINGS["response_format"],
                prompt=(
                    f"{config.API_SETTINGS['prompt']}\n\nVocabulary hints: {config.VOCABULARY_HINT}."
                ),
            )
    except Exception as exc:
        self._log(f"OpenAI transcription failed: {exc}")
        return None

async def _commit_and_request(self) -> None:
    if not self.websocket:
        return
    while self.pending_futures:
        future = self.pending_futures.popleft()
        try:
            future.result(timeout=5)
        except Exception as exc:
            self.log(f"Audio chunk send error: {exc!r}")
    await self.websocket.send(json.dumps({"type": "input_audio_buffer.commit"}))
    await self.websocket.send(
        json.dumps(
            {
                "type": "response.create",
                "response": {"instructions": self.instructions},
            }
        )
    )

