def _discover_fedora_via_tailscale(self):
    """Discover Fedora server hostname via Tailscale (like reference script)"""
    import subprocess

    try:
        # Check if tailscale command is available
        result = subprocess.run(
            ["tailscale", "status"],
            capture_output=True,
            text=True,
            timeout=5
        )

        if result.returncode == 0:
            # Look for "fedora" hostname (case-insensitive)
            for line in result.stdout.splitlines():
                # Tailscale status format: <hostname> <ip> ...
                parts = line.strip().split()
                if parts:
                    hostname = parts[0].lower()
                    if "fedora" in hostname:
                        # Return the actual hostname (first part)
                        return parts[0]

            # Also look for hostnames containing "qwen" or "ollama"
            for line in result.stdout.splitlines():
                parts = line.strip().split()
                if parts:
                    hostname = parts[0].lower()
                    if "qwen" in hostname or "ollama" in hostname:
                        return parts[0]
    except (subprocess.TimeoutExpired, FileNotFoundError, Exception) as e:
        self._log(f"Could not discover via Tailscale: {e}", "DEBUG")

    return None

